INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(17818, 'koKR', 'Golem. Polecenie. Raport o stanie operacyjnym.', 'Golem. Polecenie. Raport o stanie operacyjnym.', 0),
(17820, 'koKR', 'Ta jednostka działa obecnie z dziewięćdziesięciopięcioprocentową sprawnością operacyjną.', '', 0),
(17821, 'koKR', 'Ta jednostka działa obecnie w normalnych parametrach.', '', 0),
(17839, 'koKR', 'Ruchy golema wydają się zgodne ze specyfikacją.', 'Ruchy golema wydają się zgodne ze specyfikacją.', 0),
(17840, 'koKR', 'Ucieszę się, gdy końcowe testy tej jednostki dobiegną końca.', 'Ucieszę się, gdy końcowe testy tej jednostki dobiegną końca.', 0),
(17841, 'koKR', 'Po tym teście mobilności zostanie nam już tylko końcowa kontrola uzbrojenia.', 'Po tym teście mobilności zostanie nam już tylko końcowa kontrola uzbrojenia.', 0),
(18030, 'koKR', 'Pierwszy oddział gotowy do boju!', 'Pierwszy oddział gotowy do boju!', 0),
(18031, 'koKR', 'Czysto!', 'Czysto!', 0),
(18032, 'koKR', 'Jesteśmy gotowi bronić Oka!', 'Jesteśmy gotowi bronić Oka!', 0),
(18035, 'koKR', 'Drugi oddział gotowy do walki!', 'Drugi oddział gotowy do walki!', 0),
(18036, 'koKR', 'Wróg się przez nas nie przedrze!', 'Wróg się przez nas nie przedrze!', 0),
(18037, 'koKR', 'Nasze ostrza i zaklęcia są w gotowości!', 'Nasze ostrza i zaklęcia są w gotowości!', 0),
(18038, 'koKR', 'Trzeci oddział melduje się!', 'Trzeci oddział melduje się!', 0),
(18039, 'koKR', 'Nie okażemy wrogom litości!', 'Nie okażemy wrogom litości!', 0),
(18040, 'koKR', 'Nasza obrona jest w gotowości!', 'Nasza obrona jest w gotowości!', 0),
(18045, 'koKR', 'Spocznij!', 'Spocznij!', 0),
(18046, 'koKR', 'Zachowajcie czujność.', 'Zachowajcie czujność.', 0),
(18047, 'koKR', 'Dobrze.', 'Dobrze.', 0),
(18048, 'koKR', 'Doskonała robota.', 'Doskonała robota.', 0),
(18049, 'koKR', 'Wasza postawa napawa mnie dumą.', 'Wasza postawa napawa mnie dumą.', 0),
(18259, 'koKR', 'Pokłońcie się mojej woli.', '', 0),
(19003, 'koKR', 'Przetrwaliście starcie z kilkoma z moich najlepszych doradców... ale nikt nie oprze się potędze Krwawego Młota. Oto lord Sanguinar!', '', 0),
(19004, 'koKR', 'Capernian dopilnuje, by wasz pobyt tutaj był krótki.', '', 0),
(19005, 'koKR', 'Dobra robota, okazaliście się godni, by zmierzyć się z moim mistrzem inżynierem, Telonicusem.', '', 0),
(19006, 'koKR', 'Zobaczmy, jak wytrzymają wasze nerwy w starciu z Zaciemniaczem, Thaladredem!', '', 0),
(19053, 'koKR', 'Jak widzicie, mam w swoim arsenale wiele broni...', '', 0),
(19060, 'koKR', 'Może was nie doceniłem. Byłoby nieuczciwie kazać wam walczyć ze wszystkimi czterema doradcami naraz, ale... mój lud nigdy nie zaznał uczciwego traktowania. Ja tylko odwzajemniam przysługę.', '', 0),
(19195, 'koKR', 'Cóż, czasem trzeba wziąć sprawy we własne ręce. Balamore shanal!', '', 0),
(20195, 'koKR', 'Energia. Moc. Mój lud jest od niej uzależniony... ta zależność ujawniła się po zniszczeniu Słonecznej Studni. Witajcie w przyszłości. Szkoda, że jesteście za późno, by ją powstrzymać. Teraz nikt mnie nie powstrzyma! Selama ashal\'anore!', '', 0),
(20198, 'koKR', 'Zobaczmy, jak sobie poradzicie, gdy wasz świat stanie na głowie.', '', 0),
(20199, 'koKR', 'Trudno utrzymać się przy ziemi?', '', 0),
(20200, 'koKR', 'Na moc słońca!', '', 0),
(20201, 'koKR', 'Anar\'anel belore!', '', 0),
(20202, 'koKR', 'Słuchaj mnie!', '', 0),
(20204, 'koKR', 'Nie zwyciężycie!', '', 0),
(20205, 'koKR', 'Zaryzykowaliście. I przegraliście.', '', 0),
(20206, 'koKR', 'To była dziecinna igraszka.', '', 0),
(20207, 'koKR', 'Za... Quel\'...Thalas!', '', 0),
(20208, 'koKR', 'Nie zaszedłem tak daleko, by ktoś mnie teraz powstrzymał! Nie pozwolę zagrozić przyszłości, którą zaplanowałem! Teraz zakosztujecie prawdziwej mocy!!', '', 0),
(20372, 'koKR', 'Dość tego! Teraz przyzywam gniew samego kosmosu.', 'Dość tego! Teraz przyzywam gniew samego kosmosu.', 0),
(20373, 'koKR', 'Staję się JEDNYM... z PUSTKĄ!', 'Staję się JEDNYM... z PUSTKĄ!', 0),
(20775, 'koKR', '%s zaczyna rzucać Pirowybuch!', '', 0),
(20847, 'koKR', '', 'Sin\'dorei panują niepodzielnie!', 0),
(20848, 'koKR', '', 'To jeszcze nie koniec!', 0),
(20849, 'koKR', '', 'Tal anu\'men no sin\'dorei!', 0),
(20850, 'koKR', '', 'Ciepło słońca... czeka.', 0),
(20851, 'koKR', '', 'Twoja dusza należy do otchłani!', 0),
(20852, 'koKR', '', 'Na krew Wysoko Urodzonych!', 0),
(20853, 'koKR', '', 'Za Słoneczną Studnię!', 0),
(20854, 'koKR', '', 'Nie macie żadnych szans!', 0),
(20855, 'koKR', '', 'Zmiażdżę wasze urojenia o wielkości!', 0),
(20858, 'koKR', 'NIE! Ja... nie... pozwolę...', '', 0),
(20859, 'koKR', 'Krew za krew!', '', 0),
(20861, 'koKR', 'Kolejne niebezpieczeństwa... czekają...', '', 0),
(20904, 'koKR', 'Wybacz mi, mój książę! Ja... zawiodłem.', '', 0),
(20906, 'koKR', 'Alarm! Zostaliście przeznaczeni do eksterminacji.', '', 0),
(20907, 'koKR', 'Systemy... wyłą... cza... ją... się...', '', 0),
(20908, 'koKR', 'Eksterminacja zakończona powodzeniem.', '', 0),
(20909, 'koKR', 'Inwazyjna forma życia przestała funkcjonować.', '', 0),
(20910, 'koKR', 'Zagrożenie zneutralizowane.', '', 0),
(20911, 'koKR', 'Rozpoczynam środki alternatywne...', '', 0),
(20912, 'koKR', 'Obliczanie parametrów siły...', '', 0),
(35758, 'koKR', 'Przygotujcie się!', '', 0);
